class QuantumBool{constructor(t){t||(t=Math.random()),t>1&&(t=1),t<0&&(t=0),this.tpercent=t,this.fpercent=1-t}observe(){return Math.random()>this.tpercent?(this.tpercent=0,this.fpercent=1,!1):(this.tpercent=1,this.fpercent=0,!0)}observeWithoutCollapse(){return!(Math.random()>this.tpercent)}setPercent(t){this.tpercent=t,this.fpercent=1-t}getPercent(){return{false:this.fpercent,true:this.tpercent}}randomizePercent(){this.tpercent=Math.random(),this.fpercent=1-this.tpercent}}window.QuantumBool=QuantumBool;